import java.util.*; import java.io.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); long N = Long.parseLong(st.nextToken()); int M = Integer.parseInt(st.nextToken()); long T = Long.parseLong(st.nextToken()); long[] finalPositions = new long[M]; for (int i = 0; i < M; i++) { st = new StringTokenizer(br.readLine()); long x = Long.parseLong(st.nextToken()); int y = Integer.parseInt(st.nextToken()); long pos = (x - 1 + (y * (T % N))) % N; if (pos < 0) pos += N; finalPositions[i] = pos + 1; } Arrays.sort(finalPositions); StringBuilder sb = new StringBuilder(); for (int i = 0; i < M; i++) { sb.append(finalPositions[i]).append(i == M - 1 ? "" : " "); } System.out.println(sb.toString()); } }